using Microsoft.Extensions.DependencyInjection;
using Takt.Domain.Entities.Foundation;
using Takt.Domain.Interfaces;
using Takt.Domain.Repositories;
using Takt.Shared.Helpers;

namespace Takt.Infrastructure.Data.Seeds.EntitySeedData;

/// <summary>
/// 字典数据种子数据初始化
/// 幂等性操作：存在则更新，不存在则创建
/// 注意：每个租户数据库只初始化自己的字典数据
/// Program.cs 会为每个租户数据库调用此方法，因此只需为当前租户初始化字典数据
/// </summary>
public class TaktDictDataSeedData : ITaktSeedDataCoordinator
{
    /// <summary>
    /// 执行顺序（在 DictType 之后）
    /// </summary>
    public int Order => 46;

    /// <summary>
    /// 初始化字典数据种子数据
    /// </summary>
    /// <param name="serviceProvider">服务提供者</param>
    /// <param name="tenantCode">租户编码（由协调器传入）</param>
    /// <returns>返回插入和更新的记录数（插入数, 更新数）</returns>
    public async Task<(int InsertCount, int UpdateCount)> SeedAsync(IServiceProvider serviceProvider, string? tenantCode = null)
    {
        TaktLogger.Information("开始初始化字典数据种子数据...");

        // 参数验证
        if (string.IsNullOrEmpty(tenantCode))
        {
            TaktLogger.Warning("租户编码为空，跳过字典数据种子数据初始化");
            return (0, 0);
        }

        var dictDataRepository = serviceProvider.GetRequiredService<ITaktTenantSeedRepository<TaktDictData>>();
        var dictTypeRepository = serviceProvider.GetRequiredService<ITaktTenantSeedRepository<TaktDictType>>();
        var dictTypeIdByCode = await LoadDictTypeIdCacheAsync(dictTypeRepository, tenantCode);

        int insertCount = 0;
        int updateCount = 0;

        TaktLogger.Information("正在为租户 {TenantCode} 初始化字典数据...", tenantCode);

        // 为当前租户初始化标准字典数据
        var dictDataList = GetStandardDictData();
        foreach (var dictDataItem in dictDataList)
        {
            var (dictData, isInserted) = await CreateOrUpdateDictDataAsync(
                dictDataRepository,
                dictTypeIdByCode,
                tenantCode,
                dictDataItem.DictTypeCode,
                dictDataItem.DictLabel,
                dictDataItem.DictValue,
                dictDataItem.I18nKey,
                dictDataItem.ListClass,
                dictDataItem.CssClass,
                dictDataItem.IsDefault,
                dictDataItem.Remark,
                dictDataItem.SortOrder);
            
            insertCount += (isInserted ? 1 : 0);
            updateCount += (isInserted ? 0 : 1);
        }

        TaktLogger.Information("字典数据种子数据初始化完成: 插入 {InsertCount} 条，更新 {UpdateCount} 条", insertCount, updateCount);

        return (insertCount, updateCount);
    }

