    /// <summary>
    /// 加载当前租户字典类型编码与 ID 映射（DictType 种子 Order=45，本类 Order=46，类型已就绪）
    /// </summary>
    /// <param name="dictTypeRepository">字典类型仓储</param>
    /// <param name="tenantCode">租户编码</param>
    /// <returns>DictTypeCode → DictTypeId</returns>
    private static async Task<Dictionary<string, long>> LoadDictTypeIdCacheAsync(
        ITaktTenantSeedRepository<TaktDictType> dictTypeRepository,
        string tenantCode)
    {
        var dictTypes = await dictTypeRepository.GetListAsync(d => d.TenantCode == tenantCode);
        return dictTypes.ToDictionary(d => d.DictTypeCode, d => d.Id, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>
    /// 按字典类型编码解析 DictTypeId
    /// </summary>
    /// <param name="dictTypeIdByCode">字典类型编码缓存</param>
    /// <param name="tenantCode">租户编码</param>
    /// <param name="dictTypeCode">字典类型编码</param>
    /// <returns>字典类型 ID</returns>
    private static long ResolveDictTypeId(
        Dictionary<string, long> dictTypeIdByCode,
        string tenantCode,
        string dictTypeCode)
    {
        if (!dictTypeIdByCode.TryGetValue(dictTypeCode, out var dictTypeId))
        {
            throw new InvalidOperationException(
                $"字典类型不存在，无法初始化字典数据: TenantCode={tenantCode}, DictTypeCode={dictTypeCode}");
        }
        return dictTypeId;
    }

    /// <summary>
    /// 创建或更新字典数据
    /// </summary>
    /// <param name="repository">字典数据仓储</param>
    /// <param name="dictTypeIdByCode">字典类型编码缓存</param>
    /// <param name="tenantCode">租户编码</param>
    /// <param name="dictTypeCode">字典类型编码</param>
    /// <param name="dictLabel">字典标签</param>
    /// <param name="dictValue">字典值</param>
    /// <param name="i18nKey">国际化翻译键</param>
    /// <param name="listClass">列表样式类</param>
    /// <param name="cssClass">CSS类名</param>
    /// <param name="isDefault">是否默认项</param>
    /// <param name="remark">备注</param>
    /// <param name="sortOrder">排序</param>
    /// <returns>(字典数据实体, 是否为新插入)</returns>
    private static async Task<(TaktDictData DictData, bool IsInserted)> CreateOrUpdateDictDataAsync(
        ITaktTenantSeedRepository<TaktDictData> repository,
        Dictionary<string, long> dictTypeIdByCode,
        string tenantCode,
        string dictTypeCode,
        string dictLabel,
        string dictValue,
        string i18nKey,
        int listClass,
        int cssClass,
        int isDefault,
        string remark,
        int sortOrder)
    {
        var dictTypeId = ResolveDictTypeId(dictTypeIdByCode, tenantCode, dictTypeCode);
        // 幂等键：租户 + 字典类型编码 + DictValue + DictLabel（兼容历史 DictTypeId=0 记录）
        var dictData = await repository.FirstAsync(d =>
            d.TenantCode == tenantCode &&
            d.DictTypeCode == dictTypeCode &&
            d.DictValue == dictValue &&
            d.DictLabel == dictLabel);
        if (dictData == null)
        {
            dictData = new TaktDictData
            {
                TenantCode = tenantCode,
                DictTypeId = dictTypeId,
                DictTypeCode = dictTypeCode,
                DictLabel = dictLabel,
                DictValue = dictValue,
                I18nKey = i18nKey,
                ListClass = listClass,
                CssClass = cssClass,
                IsDefault = isDefault,
                Remark = remark,
                SortOrder = sortOrder
            };
            dictData = await repository.CreateAsync(dictData);
            return (dictData, true);
        }
        dictData.DictTypeId = dictTypeId;
        dictData.DictTypeCode = dictTypeCode;
        dictData.DictLabel = dictLabel;
        dictData.I18nKey = i18nKey;
        dictData.ListClass = listClass;
        dictData.CssClass = cssClass;
        dictData.IsDefault = isDefault;
        dictData.Remark = remark;
        dictData.SortOrder = sortOrder;
        await repository.UpdateAsync(dictData);
        return (dictData, false);
    }
}
